def gravity(g):
    g=[[0]*W for _ in range(H)]
    # collect pieces: connected comps of non-zero
    seen=set(); pieces=[]
    for i in range(H):
        for j in range(W):
            v=g[i][j]
            if v and (i,j) not in seen:
                st=[(i,j)]; col=v; c=[]
                while st:
                    a,b=st.pop()
                    if (a,b) in seen: continue
                    seen.add((a,b)); c.append((a,b))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dx,b+dy
                        if 0<=x<H and 0<=y<W and g[x][y]==v: st.append((x,y))
                pieces.append((col,c,(min(r for r,_ in c),min(cc for _,cc in c))))
    # simulate: drop each piece to bottom (floor/other pieces) keeping column range
    occupied=set()
    for col,cells,pos in pieces:
        # find resting position: maximal down shift without overlapping occupied
        r=pos[0]; cpos=pos[1]
        while True:
            nr=r+1
            if all(nr+dr < H and (nr+dr,cpos+dc) not in occupied for dr,dc in [(0,0)]) and False: pass
            ok=True
            for dr,dc in cells:
                if nr+dr>=H or (nr+dr,cpos+dc) in occupied: ok=False;break
            if ok: r=nr
        for dr,dc in cells:
            occupied.add((r+dr,cpos+dc))
            g[r+dr][cpos+dc]=col
    return g
