        seen=set(); out=[]
        for i in range(H):
            for j in range(W):
                if g[i][j]==val and (i,j) not in seen:
                    st=[(i,j)]; cells=[]
                    while st:
                        y,x=st.pop()
                        if (y,x) in seen: continue
                        seen.add((y,x)); cells.append((y,x))
                        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==val: st.append((ny,nx))
                    out.append(cells)
        return out
    pieces=[]
    for val in {x for row in g for x in row if x}:
        for cells in comps(g,val):
            mnr=min(y for y,_ in cells); mnc=min(x for _,x in cells)
            pieces.append({'v':val,'cells':sorted(set(cells)),
                           'sig':tuple(sorted((y-mnr,x-mnc) for y,x in cells)),
                           'r0':mnr,'c0':mnc,'h':max(y for y,_ in cells)-mnr+1,
                           'w':max(x for _,x in cells)-mnc+1,'sz':len(cells)})
    # order colors by min col, bands
    bands={}
    for p in pieces: bands.setdefault(p['v'],[]).append(p)
    order=sorted(bands, key=lambda v: min(p['c0'] for p in bands[v]))
    out=[[0]*W for _ in range(H)]
    col=0; prev_w=0
    for v in order:
        ps=sorted(bands[v], key=lambda p:-p['c0'])  # rightmost orig col on top
        band=[]
        for p in ps: band.append({'h':p['h'],'w':p['w'],'sz':p['sz'],'sig':p['sig'],'v':p['v']})
        bw=max(p['w'] for p in ps)
        # top row: stack bottom up with 1-gap; bottom piece at floor; gap0 only when bottom piece h==1
        total=sum(p['h'] for p in band)+(len(band)-1)
        top=H-total
        # handle the anomaly: gap before a 1-tall floor piece -> reduce
        # implement: place bottom-up contiguous; then lift pieces above the floor piece by 1 if floor piece h==1? simpler: explicit
        rows_used=[]
        cur_rows=[H-1-(sum(q['h'] for q in band)+ (len(band)-1))]  # tentative
        # proper: place bottom piece at floor, others 1 above... test empirically below
        for k,p in enumerate(band):
            pass
        # concrete: if band[-1]['h']==1: gap between band[-2] and band[-1] is 0 => top = H - (sum h + (n-2))
        top = H - (sum(p['h'] for p in band) + len(band)-1)
        if band and band[-1]['h']==1:
            top = H - (sum(p['h'] for p in band) + len(band)-2)
        row=top
        for k,p in enumerate(band):
            for i in range(p['h']):
                for j in range(p['w']):
                    rr=row+i
                    cc=col+j
                    if out[rr][cc]==0: out[rr][cc]=p['v']
            row+=p['h']+1 if k<len(band)-1 or (p['h']>1) else 0
        col+=bw+1
    return out

